import json,sys
d=json.load(sys.stdin)
out=[]
for it in d.get('items',[]):
    pv=(it.get('metadata') or {}).get('provenance') or {}
    t=pv.get('task','')
    if not t.startswith(('ajc-p','review-ajc')) or t.startswith('ajcr'): continue
    try: r=int(pv.get('round','-1'))
    except: r=-1
    if r>=5: out.append((it.get('updated_at',''),it['id'],it['kind'],t,r,(it.get('body') or '')[:200].replace('\n',' ')))
out.sort(reverse=True)
for o in out[:25]: print(o[1],o[2],o[3],'r'+str(o[4]),o[0][5:16],'|',o[5]); print()
"

